@Transactional
public TaskView scheduleTask(String incidentKey, String taskKey, String actor, TaskScheduleRequest req) {
    String requestId = requireText(req.requestId(), "requestId");
    String assignee = requireText(req.assignee(), "assignee");
    if (req.expectedTaskVersion() == null) throw badRequest("expectedTaskVersion 不能为空");
    Instant startAt = requireMinuteAligned(req.startAt(), "startAt");
    Instant endAt = requireMinuteAligned(req.endAt(), "endAt");
    long minutes = Duration.between(startAt, endAt).toMinutes();
    if (minutes < 1 || minutes > 240) throw badRequest("执行时段长度须为 1~240 分钟");
    Incident incident = lockIncident(incidentKey);
    requireCommander(incident, actor);  // 权限先于重放
    return runIdempotent(requestId, "task_schedule",
            structuredHash(incidentKey, taskKey, actor, req.expectedTaskVersion(), assignee, startAt.toString(), endAt.toString()),
            TaskView.class, () -> {
                IncidentTask task = tasks.findByKey(incident.id(), taskKey).orElseThrow(notFound);
                if (task.status() != TaskStatus.OPEN) throw conflict("任务已处于终态...");
                requireVersion(task, req.expectedTaskVersion());
                schedules.lockPerson(assignee);
                var existing = schedules.findByTask(task.id());
                if (existing.isPresent() && existing.get().status() == STARTED) throw conflict("安排已开始，不可改时");
                validateDutyRules(assignee, startAt, endAt, task.id());
                Instant now = now();
                if (existing.isPresent() && existing.get().status() == SCHEDULED) {
                    schedules.replace(existing.get().id(), assignee, startAt, endAt, now);
                } else {
                    schedules.insert(new TaskSchedule(0L, task.id(), assignee, startAt, endAt, SCHEDULED, null, now, now));
                }
                tasks.bumpVersion(task.id(), now);
                return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
            });
}
