        assertThat(ok.schedule().status()).isEqualTo("SCHEDULED");
        // 时段重叠同样视为休息不足 → 422
        createTask("INC-R2", "alice", "T-3");
        assertApiStatus(() -> service.scheduleTask("INC-R2", "T-3", "alice",
