@SpringBootTest
@AutoConfigureMockMvc
@Import(ControllableClock.Config.class)
class TaskScheduleApiTest {

    private static final Instant T0 = Instant.parse("2026-10-06T00:00:00Z");

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcTemplate jdbc;

    @Autowired
    private Clock clock;

    @BeforeEach
